--
-- Disparadores `nexoapp_comprasuscripcion`
--
DELIMITER $$
CREATE TRIGGER `tr_fact_suscripciones_delete` AFTER DELETE ON `nexoapp_comprasuscripcion` FOR EACH ROW BEGIN
    DELETE FROM etl_dw_nexotech.fact_suscripciones
    WHERE id_compra = OLD.id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_fact_suscripciones_insert` AFTER INSERT ON `nexoapp_comprasuscripcion` FOR EACH ROW BEGIN
    DECLARE v_idtiempo INT;
    SET v_idtiempo = CAST(DATE_FORMAT(NEW.fecha_compra, '%Y%m%d') AS UNSIGNED);
    INSERT IGNORE INTO etl_dw_nexotech.dim_tiempo
    (id_tiempo, fecha, anio, mes, dia, trimestre)
    VALUES
    (v_idtiempo,
     NEW.fecha_compra,
     YEAR(NEW.fecha_compra),
     MONTH(NEW.fecha_compra),
     DAY(NEW.fecha_compra),
     QUARTER(NEW.fecha_compra));
    INSERT INTO etl_dw_nexotech.fact_suscripciones
    (id_compra, id_tiempo, proveedor_id, suscripcion_id,
     estado, monto_pagado, metodo_pago, es_renovacion)
    VALUES
    (NEW.id, v_idtiempo, NEW.proveedor_id, NEW.suscripcion_id,
     NEW.estado, NEW.monto_pagado, NEW.metodo_pago, NEW.es_renovacion);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_fact_suscripciones_update` AFTER UPDATE ON `nexoapp_comprasuscripcion` FOR EACH ROW BEGIN
    DECLARE v_idtiempo INT;
    SET v_idtiempo = CAST(DATE_FORMAT(NEW.fecha_compra, '%Y%m%d') AS UNSIGNED);
    INSERT IGNORE INTO etl_dw_nexotech.dim_tiempo
    (id_tiempo, fecha, anio, mes, dia, trimestre)
    VALUES
    (v_idtiempo,
     NEW.fecha_compra,
     YEAR(NEW.fecha_compra),
     MONTH(NEW.fecha_compra),
     DAY(NEW.fecha_compra),
     QUARTER(NEW.fecha_compra));
    UPDATE etl_dw_nexotech.fact_suscripciones
    SET
        id_tiempo      = v_idtiempo,
        proveedor_id   = NEW.proveedor_id,
        suscripcion_id = NEW.suscripcion_id,
        estado         = NEW.estado,
        monto_pagado   = NEW.monto_pagado,
        metodo_pago    = NEW.metodo_pago,
        es_renovacion  = NEW.es_renovacion
    WHERE id_compra = NEW.id;
END
$$
DELIMITER ;

