--
-- Disparadores `nexoapp_itemventa`
--
DELIMITER $$
CREATE TRIGGER `tr_fact_ventas_from_item_delete` AFTER DELETE ON `nexoapp_itemventa` FOR EACH ROW BEGIN
    DELETE FROM etl_dw_nexotech.fact_ventas
    WHERE id_venta    = OLD.venta_id
      AND id_producto = OLD.producto_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_fact_ventas_from_item_insert` AFTER INSERT ON `nexoapp_itemventa` FOR EACH ROW BEGIN
    DECLARE v_idtiempo      INT;
    DECLARE v_idcliente     BIGINT;
    DECLARE v_idproveedor   BIGINT;
    DECLARE v_metodopago    VARCHAR(50);
    DECLARE v_fechaventa    DATETIME(6);
    DECLARE v_producto_nom  VARCHAR(200);
    DECLARE v_categoria_nom VARCHAR(100);
    DECLARE v_proveedor_nom LONGTEXT;
    DECLARE v_precio_unit   DECIMAL(12,2);
    SELECT v.fecha_creacion,
           v.cliente_id,
           v.proveedor_id
    INTO   v_fechaventa,
           v_idcliente,
           v_idproveedor
    FROM nexoapp_venta v
    WHERE v.id = NEW.venta_id;
    SET v_idtiempo = CAST(DATE_FORMAT(v_fechaventa, '%Y%m%d') AS UNSIGNED);
    SELECT p.nombre,
           c.nombre,
           p.precio
    INTO   v_producto_nom,
           v_categoria_nom,
           v_precio_unit
    FROM nexoapp_producto p
    JOIN nexoapp_categoria c ON p.categoria_id = c.id
    WHERE p.id = NEW.producto_id;
    IF NEW.precio_unitario IS NOT NULL AND NEW.precio_unitario <> 0 THEN
        SET v_precio_unit = NEW.precio_unitario;
    END IF;
    SELECT descripcion
    INTO   v_proveedor_nom
    FROM nexoapp_proveedor
    WHERE id = v_idproveedor;
    INSERT IGNORE INTO etl_dw_nexotech.dim_tiempo
        (id_tiempo, fecha, anio, mes, dia, trimestre)
    VALUES
        (v_idtiempo,
         v_fechaventa,
         YEAR(v_fechaventa),
         MONTH(v_fechaventa),
         DAY(v_fechaventa),
         QUARTER(v_fechaventa));
    INSERT INTO etl_dw_nexotech.dim_producto
        (id_producto, nombre, categoria, descripcion, precio, id_categoria)
    VALUES
        (NEW.producto_id, v_producto_nom, v_categoria_nom, NULL, v_precio_unit, NULL)
    ON DUPLICATE KEY UPDATE
        nombre    = VALUES(nombre),
        categoria = VALUES(categoria),
        precio    = VALUES(precio);
    INSERT INTO etl_dw_nexotech.dim_proveedor
        (id_proveedor, nombre, contacto, correo, tipo)
    VALUES
        (v_idproveedor, v_proveedor_nom, NULL, NULL, NULL)
    ON DUPLICATE KEY UPDATE
        nombre = VALUES(nombre);
    INSERT INTO etl_dw_nexotech.fact_ventas
        (id_venta, id_producto, id_cliente, id_proveedor, id_tiempo,
         cantidad, precio_unitario, total, metodo_pago)
    VALUES
        (NEW.venta_id,
         NEW.producto_id,
         v_idcliente,
         v_idproveedor,
         v_idtiempo,
         NEW.cantidad,
         v_precio_unit,
         NEW.cantidad * v_precio_unit,
         v_metodopago);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_fact_ventas_from_item_update` AFTER UPDATE ON `nexoapp_itemventa` FOR EACH ROW BEGIN
    DECLARE v_idtiempo    INT;
    DECLARE v_fechaventa  DATETIME(6);
    DECLARE v_precio_unit DECIMAL(12,2);
    SELECT v.fecha_creacion
    INTO   v_fechaventa
    FROM nexoapp_venta v
    WHERE v.id = NEW.venta_id;
    SET v_idtiempo    = CAST(DATE_FORMAT(v_fechaventa, '%Y%m%d') AS UNSIGNED);
    SET v_precio_unit = NEW.precio_unitario;
    UPDATE etl_dw_nexotech.fact_ventas
    SET cantidad        = NEW.cantidad,
        precio_unitario = v_precio_unit,
        total           = NEW.cantidad * v_precio_unit,
        id_tiempo       = v_idtiempo
    WHERE id_venta    = NEW.venta_id
      AND id_producto = NEW.producto_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_fact_ventas_item_delete` AFTER DELETE ON `nexoapp_itemventa` FOR EACH ROW BEGIN
  DELETE FROM etl_dw_nexotech.fact_ventas
  WHERE id_venta = OLD.venta_id
    AND id_producto = OLD.producto_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_fact_ventas_item_insert` AFTER INSERT ON `nexoapp_itemventa` FOR EACH ROW BEGIN
  DECLARE v_idfecha INT;
  DECLARE v_cli INT;
  DECLARE v_prov INT;
  SELECT 
    CAST(DATE_FORMAT(v.fecha_creacion,'%Y%m%d') AS UNSIGNED),
    v.cliente_id,
    v.proveedor_id
  INTO v_idfecha, v_cli, v_prov
  FROM nexoapp_venta v
  WHERE v.id = NEW.venta_id;
  INSERT INTO etl_dw_nexotech.fact_ventas
    (id_venta, id_producto, id_cliente, id_proveedor,
     id_tiempo, cantidad, precio_unitario, total, metodo_pago)
  VALUES
    (NEW.venta_id, NEW.producto_id, v_cli, v_prov,
     v_idfecha, NEW.cantidad, NEW.precio_unitario,
     NEW.subtotal, NULL);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_fact_ventas_item_update` AFTER UPDATE ON `nexoapp_itemventa` FOR EACH ROW BEGIN
  DECLARE v_idfecha INT;
  DECLARE v_cli INT;
  DECLARE v_prov INT;
  SELECT 
    CAST(DATE_FORMAT(v.fecha_creacion,'%Y%m%d') AS UNSIGNED),
    v.cliente_id,
    v.proveedor_id
  INTO v_idfecha, v_cli, v_prov
  FROM nexoapp_venta v
  WHERE v.id = NEW.venta_id;
  UPDATE etl_dw_nexotech.fact_ventas
  SET cantidad = NEW.cantidad,
      precio_unitario = NEW.precio_unitario,
      total = NEW.subtotal,
      id_tiempo = v_idfecha,
      id_cliente = v_cli,
      id_proveedor = v_prov
  WHERE id_venta = NEW.venta_id
    AND id_producto = NEW.producto_id;
END
$$
DELIMITER ;

