--
-- Disparadores `nexoapp_producto`
--
DELIMITER $$
CREATE TRIGGER `tr_dim_producto_delete` AFTER DELETE ON `nexoapp_producto` FOR EACH ROW BEGIN
  DELETE FROM etl_dw_nexotech.dim_producto
  WHERE id_producto = OLD.id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_dim_producto_insert` AFTER INSERT ON `nexoapp_producto` FOR EACH ROW BEGIN
  DECLARE v_categoria VARCHAR(255);
  SELECT nombre INTO v_categoria
  FROM nexoapp_categoria
  WHERE id = NEW.categoria_id
  LIMIT 1;
  INSERT INTO etl_dw_nexotech.dim_producto
    (id_producto, nombre, descripcion, categoria, precio, id_categoria)
  VALUES
    (NEW.id, NEW.nombre, NEW.descripcion, v_categoria, NEW.precio, NEW.categoria_id)
  ON DUPLICATE KEY UPDATE
    nombre = NEW.nombre,
    descripcion = NEW.descripcion,
    categoria = v_categoria,
    precio = NEW.precio,
    id_categoria = NEW.categoria_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_dim_producto_update` AFTER UPDATE ON `nexoapp_producto` FOR EACH ROW BEGIN
  DECLARE v_categoria VARCHAR(255);
  SELECT nombre INTO v_categoria
  FROM nexoapp_categoria
  WHERE id = NEW.categoria_id
  LIMIT 1;
  INSERT INTO etl_dw_nexotech.dim_producto
    (id_producto, nombre, descripcion, categoria, precio, id_categoria)
  VALUES
    (NEW.id, NEW.nombre, NEW.descripcion, v_categoria, NEW.precio, NEW.categoria_id)
  ON DUPLICATE KEY UPDATE
    nombre = NEW.nombre,
    descripcion = NEW.descripcion,
    categoria = v_categoria,
    precio = NEW.precio,
    id_categoria = NEW.categoria_id;
END
$$
DELIMITER ;

