--
-- Disparadores `nexoapp_proveedor`
--
DELIMITER $$
CREATE TRIGGER `tr_dim_proveedor_delete` AFTER DELETE ON `nexoapp_proveedor` FOR EACH ROW BEGIN
  DELETE FROM etl_dw_nexotech.dim_proveedor
  WHERE id_proveedor = OLD.id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_dim_proveedor_insert` AFTER INSERT ON `nexoapp_proveedor` FOR EACH ROW BEGIN
  INSERT INTO etl_dw_nexotech.dim_proveedor
    (id_proveedor, nombre, contacto, correo, tipo)
  VALUES
    (NEW.id, NEW.descripcion, NEW.sitio_web, NULL, NEW.empresa_id)
  ON DUPLICATE KEY UPDATE
    nombre = NEW.descripcion,
    contacto = NEW.sitio_web,
    correo = NULL,
    tipo = NEW.empresa_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_dim_proveedor_update` AFTER UPDATE ON `nexoapp_proveedor` FOR EACH ROW BEGIN
  INSERT INTO etl_dw_nexotech.dim_proveedor
    (id_proveedor, nombre, contacto, correo, tipo)
  VALUES
    (NEW.id, NEW.descripcion, NEW.sitio_web, NULL, NEW.empresa_id)
  ON DUPLICATE KEY UPDATE
    nombre = NEW.descripcion,
    contacto = NEW.sitio_web,
    correo = NULL,
    tipo = NEW.empresa_id;
END
$$
DELIMITER ;

