--
-- Disparadores `nexoapp_venta`
--
DELIMITER $$
CREATE TRIGGER `tr_dim_fecha_cliente_from_venta` BEFORE INSERT ON `nexoapp_venta` FOR EACH ROW BEGIN
  DECLARE v_idfecha INT;
  SET v_idfecha = CAST(DATE_FORMAT(NEW.fecha_creacion,'%Y%m%d') AS UNSIGNED);
  INSERT IGNORE INTO etl_dw_nexotech.dim_tiempo
    (id_tiempo, fecha, anio, mes, dia, trimestre)
  VALUES
    (v_idfecha, NEW.fecha_creacion,
     YEAR(NEW.fecha_creacion),
     MONTH(NEW.fecha_creacion),
     DAY(NEW.fecha_creacion),
     QUARTER(NEW.fecha_creacion));
  INSERT IGNORE INTO etl_dw_nexotech.dim_cliente
    (id_cliente, username, nombre, apellido, correo, fecha_registro)
  SELECT id, username, first_name, last_name, email, date_joined
  FROM auth_user
  WHERE id = NEW.cliente_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_dim_tiempo_cliente_from_venta` BEFORE INSERT ON `nexoapp_venta` FOR EACH ROW BEGIN
    DECLARE v_idtiempo INT;
    DECLARE v_userid   INT;
    SET v_idtiempo = CAST(DATE_FORMAT(NEW.fecha_creacion, '%Y%m%d') AS UNSIGNED);
    INSERT IGNORE INTO etl_dw_nexotech.dim_tiempo
        (id_tiempo, fecha, anio, mes, dia, trimestre)
    VALUES
        (v_idtiempo,
         NEW.fecha_creacion,
         YEAR(NEW.fecha_creacion),
         MONTH(NEW.fecha_creacion),
         DAY(NEW.fecha_creacion),
         QUARTER(NEW.fecha_creacion));
    SELECT c.userid
    INTO   v_userid
    FROM nexoapp_cliente c
    WHERE c.id = NEW.cliente_id
    LIMIT 1;
    INSERT IGNORE INTO etl_dw_nexotech.dim_cliente
        (id_cliente, username, nombre, apellido, correo, fecha_registro)
    SELECT
        u.id,
        u.username,
        u.first_name,
        u.last_name,
        u.email,
        u.date_joined
    FROM auth_user u
    WHERE u.id = v_userid;
END
$$
DELIMITER ;

